CAT = "dehpRecht"; SEG = "REC"
# Berufs- und Gesetzeskunde (Leitlinien 1.1): HeilprG, Arztvorbehalte, Patientenrechte, Werbung.
Q = [
("Was gilt nach § 1 Heilpraktikergesetz als Ausübung der Heilkunde?",
 "Berufsmäßiges Erkennen, Heilen oder Lindern von Krankheiten", ["Jede private Beratung zu gesunder Ernährung im Freundeskreis", "Nur das Verordnen von Arzneimitteln gegen Bezahlung", "Nur Behandlungen in einer eigenen angemeldeten Praxis"],
 "§ 1 Abs. 2 HeilprG: Ausübung der Heilkunde ist jede berufs- oder gewerbsmäßig vorgenommene Tätigkeit zur Feststellung, Heilung oder Linderung von Krankheiten, Leiden oder Körperschäden bei Menschen, auch im Dienst von anderen."),
("Jemand übt ohne Erlaubnis berufsmäßig die Heilkunde aus. Womit kann das nach § 5 HeilprG bestraft werden?",
 "Freiheitsstrafe bis zu einem Jahr oder Geldstrafe", ["Nur mit einem Verwarnungsgeld als Ordnungswidrigkeit", "Freiheitsstrafe bis zu zehn Jahren", "Gar nicht, solange kein Schaden entsteht"],
 "§ 5 HeilprG: Wer die Heilkunde ohne Erlaubnis ausübt, wird mit Freiheitsstrafe bis zu einem Jahr oder mit Geldstrafe bestraft. Ein Schaden ist dafür nicht nötig."),
("Ein Patient bittet Sie um ein Rezept für ein verschreibungspflichtiges Blutdruckmittel. Was gilt für Sie als Heilpraktiker?",
 "Sie dürfen es nicht verschreiben", ["Sie dürfen es auf Privatrezept verschreiben", "Sie dürfen es mit seiner Einwilligung verschreiben", "Sie dürfen es in kleinen Packungen verschreiben"],
 "Verschreibungspflichtige Arzneimittel dürfen nach § 48 AMG nur auf Verschreibung von Ärzten, Zahnärzten oder Tierärzten abgegeben werden. Heilpraktiker gehören nicht dazu."),
("Eine Patientin mit starken Tumorschmerzen bittet Sie um ein Opioid wie Morphin. Was gilt?",
 "Sie dürfen kein Betäubungsmittel verschreiben", ["Sie dürfen es bis zu einer Höchstmenge verschreiben", "Sie dürfen es mit Zustimmung des Hausarztes verschreiben", "Sie dürfen es verschreiben, wenn Sie alles dokumentieren"],
 "Betäubungsmittel dürfen nach § 13 BtMG nur Ärzte, Zahnärzte und Tierärzte verschreiben. Verweisen Sie die Patientin an ihren behandelnden Arzt."),
("Ein Patient möchte, dass Sie die Entzündung an einer Zahnwurzel behandeln. Was gilt?",
 "Die Zahnheilkunde ist Zahnärzten vorbehalten", ["Sie ist mit der allgemeinen Erlaubnis erlaubt", "Sie ist erlaubt, wenn Sie örtlich betäuben", "Sie ist bei Notfällen am Wochenende erlaubt"],
 "Nach dem Zahnheilkundegesetz darf die Zahnheilkunde nur ausüben, wer als Zahnarzt approbiert ist. Die Heilpraktikererlaubnis umfasst sie nicht."),
("Wer darf nach dem Hebammengesetz Geburtshilfe leisten?",
 "Hebammen sowie Ärztinnen und Ärzte", ["Auch Heilpraktiker mit allgemeiner Erlaubnis", "Jede Person mit einem Kurs in Erster Hilfe", "Heilpraktiker mit einer Zusatzschulung"],
 "Geburtshilfe ist nach dem Hebammengesetz Hebammen und Ärzten vorbehalten. Kommt es unerwartet zu einer Geburt, muss trotzdem jeder bis zum Eintreffen des Rettungsdienstes Erste Hilfe leisten."),
("Aussagen zu Tätigkeiten in einer Heilpraktikerpraxis: (1) Verschreiben verschreibungspflichtiger Arzneimittel (2) Röntgenuntersuchungen am Menschen (3) Messen des Blutdrucks (4) Behandlung einer Gonorrhö. Welche Tätigkeiten sind Heilpraktikern verboten?",
 "Nur 1, 2 und 4", ["Nur 1 und 2", "Nur 2, 3 und 4", "Nur 1 und 4"],
 "Verschreibungspflichtige Arzneimittel sind Ärzten vorbehalten (§ 48 AMG), Röntgen am Menschen setzt nach dem Strahlenschutzrecht einen Arzt mit Fachkunde voraus, und sexuell übertragbare Krankheiten fallen unter das Behandlungsverbot des § 24 IfSG. Blutdruck messen darf jeder Heilpraktiker."),
("Woraus ergibt sich vor allem die Schweigepflicht eines Heilpraktikers?",
 "Aus dem Behandlungsvertrag und dem Datenschutzrecht", ["Aus § 203 StGB, der Heilpraktiker ausdrücklich nennt", "Aus einer Vorschrift im Heilpraktikergesetz", "Für Heilpraktiker gibt es keine Schweigepflicht"],
 "§ 203 StGB erfasst Heilberufe mit staatlich geregelter Ausbildung; Heilpraktiker gehören nach herrschender Meinung nicht dazu. Ihre Pflicht zur Verschwiegenheit folgt aus dem Behandlungsvertrag (§ 630a BGB ff.) und der DSGVO. Gesundheitsdaten sind besonders geschützt."),
("Ein Strafgericht lädt Sie als Zeugen zu einem Ihrer Patienten. Steht Ihnen ein Zeugnisverweigerungsrecht nach § 53 StPO zu?",
 "Nein, Heilpraktiker sind dort nicht genannt", ["Ja, im selben Umfang wie Ärzte", "Ja, aber nur für gestellte Diagnosen", "Ja, wenn der Patient es schriftlich verlangt"],
 "§ 53 StPO zählt Ärzte, Zahnärzte, Psychotherapeuten, Apotheker und Hebammen auf, nicht aber Heilpraktiker. Sie müssen im Strafverfahren grundsätzlich aussagen."),
("Wie muss nach § 630e BGB die Aufklärung vor einem Eingriff erfolgen?",
 "Mündlich, rechtzeitig und verständlich", ["Allein durch ein unterschriebenes Formular", "Erst nach dem Eingriff, wenn alles gut ging", "Nur dann, wenn der Patient ausdrücklich fragt"],
 "§ 630e Abs. 2 BGB: Die Aufklärung muss mündlich durch den Behandelnden erfolgen, so rechtzeitig, dass der Patient wohlüberlegt entscheiden kann, und für ihn verständlich sein. Ergänzend darf auf Unterlagen in Textform Bezug genommen werden."),
("Wie lange ist die Patientenakte nach § 630f BGB nach Abschluss der Behandlung aufzubewahren, wenn keine andere Vorschrift gilt?",
 "10 Jahre", ["15 Jahre", "20 Jahre", "30 Jahre"],
 "§ 630f Abs. 3 BGB: Die Patientenakte ist für die Dauer von zehn Jahren nach Abschluss der Behandlung aufzubewahren, soweit nicht nach anderen Vorschriften andere Fristen gelten."),
("Ein Patient verlangt Einsicht in seine Patientenakte. Was gilt nach § 630g BGB?",
 "Er darf sie einsehen und Abschriften verlangen", ["Nur mit Zustimmung des Gesundheitsamts", "Nur über einen Rechtsanwalt nach Behandlungsende", "Die Akte gehört allein dem Behandelnden"],
 "§ 630g BGB: Dem Patienten ist auf Verlangen unverzüglich Einsicht in die vollständige Patientenakte zu gewähren, soweit keine erheblichen therapeutischen Gründe oder Rechte Dritter entgegenstehen. Er kann Abschriften verlangen."),
("Sie setzen eine Injektion, ohne dass der Patient wirksam eingewilligt hat. Was kann darin strafrechtlich liegen?",
 "Eine Körperverletzung", ["Nur ein Verstoß gegen eine Berufsordnung", "Eine Ordnungswidrigkeit nach dem IfSG", "Nichts, wenn die Spritze medizinisch sinnvoll war"],
 "Ein Eingriff in die körperliche Unversehrtheit ist nur durch eine wirksame Einwilligung nach ausreichender Aufklärung gerechtfertigt. Fehlt sie, kommt eine Körperverletzung nach § 223 StGB in Betracht."),
("Für die Behandlung welcher Erkrankung darf nach § 12 Heilmittelwerbegesetz außerhalb der Fachkreise nicht geworben werden?",
 "Bösartige Neubildungen", ["Verspannungen im Nackenbereich", "Leichte Einschlafstörungen", "Gewöhnliche Erkältungsbeschwerden"],
 "Die Anlage zu § 12 HWG nennt unter anderem meldepflichtige Infektionskrankheiten, bösartige Neubildungen, Suchtkrankheiten außer Nikotinabhängigkeit und krankhafte Komplikationen von Schwangerschaft, Entbindung und Wochenbett."),
("Welche Aussage auf der Internetseite einer Praxis ist nach § 3 Heilmittelwerbegesetz irreführend?",
 "„Erfolg garantiert, ganz ohne Nebenwirkungen“", ["„Termine nach telefonischer Vereinbarung“", "„Die Praxis liegt im Erdgeschoss“", "„Abrechnung nach privater Gebührenvereinbarung“"],
 "§ 3 HWG verbietet irreführende Werbung, etwa wenn fälschlich der Eindruck erweckt wird, ein Erfolg könne mit Sicherheit erwartet werden oder es träten keine schädlichen Wirkungen ein."),
("Ein Heilpraktiker wendet eine invasive Behandlungsmethode an. Welcher Sorgfaltsmaßstab gilt nach der Rechtsprechung des BGH?",
 "Derselbe wie für einen Arzt mit dieser Methode", ["Ein geringerer, weil er kein Arzt ist", "Keiner, wenn der Patient eine Erklärung unterschreibt", "Nur der Maßstab seiner Heilpraktikerschule"],
 "Nach dem BGH (Urteil vom 29.01.1991, VI ZR 206/90) muss ein Heilpraktiker, der invasive Methoden anwendet, dieselben Sorgfaltspflichten erfüllen wie ein Arzt, der diese Methoden anwendet, und sich über ihre Risiken informieren."),
("Darf ein Heilpraktiker apothekenpflichtige, aber nicht verschreibungspflichtige Arzneimittel in seiner Praxis an Patienten verkaufen?",
 "Nein, die Abgabe ist Apotheken vorbehalten", ["Ja, wenn er sie selbst eingekauft hat", "Ja, bis zu einer Packung je Patient", "Ja, wenn der Patient privat versichert ist"],
 "Apothekenpflichtige Arzneimittel dürfen nach § 43 AMG für den Endverbrauch nur in Apotheken in den Verkehr gebracht werden. In der Praxis darf der Heilpraktiker sie am Patienten anwenden, aber nicht an ihn verkaufen."),
("Eine Patientin hat seit Wochen ungewollt an Gewicht verloren, nachts schwitzt sie stark und hat leichtes Fieber. Was ist Ihre wichtigste Pflicht?",
 "Rasch eine ärztliche Abklärung veranlassen", ["Zunächst eine längere Fastenkur zur Entgiftung empfehlen", "Abwarten und in drei Monaten kontrollieren", "Ausschließlich pflanzliche Mittel geben"],
 "Gewichtsverlust, Nachtschweiß und Fieber (B-Symptomatik) können auf Tuberkulose, Lymphome oder andere bösartige Erkrankungen hinweisen. Die Grenzen der eigenen Diagnostik zu erkennen und zu überweisen, gehört zur Sorgfaltspflicht."),
("Wer haftet zivilrechtlich für einen Schaden, den Sie einem Patienten durch einen Behandlungsfehler zufügen?",
 "Sie selbst als Behandelnder", ["Allein das zuständige Gesundheitsamt", "Die Krankenkasse des Patienten", "Niemand, wenn Sie in guter Absicht handelten"],
 "Aus dem Behandlungsvertrag (§ 630a BGB) und aus unerlaubter Handlung (§ 823 BGB) haftet der Behandelnde selbst. Eine Berufshaftpflichtversicherung deckt das Risiko ab, ändert aber nichts an der Haftung."),
("Übernimmt die gesetzliche Krankenversicherung in der Regel die Kosten einer Heilpraktikerbehandlung?",
 "Nein, sie gehört nicht zu ihren Leistungen", ["Ja, vollständig und ohne Antrag", "Ja, nach Überweisung durch das Gesundheitsamt", "Ja, für die ersten zehn Behandlungen im Jahr"],
 "Ärztliche Behandlung in der GKV wird nach § 15 SGB V von Ärzten erbracht. Heilpraktikerleistungen zahlt die gesetzliche Kasse nicht; manche private Kranken- oder Zusatzversicherungen erstatten sie."),
("Aussagen zum Behandlungsvertrag nach dem BGB: (1) Über Kosten, die keine Versicherung übernimmt, ist vorher in Textform zu informieren. (2) Einträge in der Akte dürfen später ohne Kennzeichnung geändert werden. (3) Der Patient kann seine Einwilligung jederzeit formlos widerrufen. (4) Unterlagen, die der Patient zur Aufklärung unterschrieben hat, erhält er in Abschrift. Welche Aussagen treffen zu?",
 "Nur 1, 3 und 4", ["Nur 1 und 3", "Nur 2, 3 und 4", "Nur 1, 2 und 4"],
 "Richtig sind § 630c Abs. 3 (wirtschaftliche Information in Textform), § 630d Abs. 3 (formloser Widerruf) und § 630e Abs. 2 BGB (Abschriften). Nach § 630f Abs. 1 BGB müssen Änderungen den ursprünglichen Inhalt und den Zeitpunkt erkennen lassen."),
("Ein Patient bricht eine notwendige ärztliche Therapie ab, weil er nur noch zu Ihnen kommen möchte. Was müssen Sie tun?",
 "Ihn deutlich auf die Gefahren hinweisen", ["Ihn in seiner Entscheidung ausdrücklich bestärken", "Seinen Arzt ohne sein Wissen anrufen", "Die Behandlung schweigend übernehmen"],
 "Ein Heilpraktiker darf einen Patienten nicht von einer notwendigen ärztlichen Behandlung abhalten. Er muss über die Risiken des Abbruchs aufklären und dies dokumentieren; Informationen an den Arzt nur mit Einwilligung."),
("Ein Heilpraktiker schreibt „Dr. med.“ auf sein Praxisschild, ohne diesen Grad erworben zu haben. Was gilt?",
 "Das ist strafbarer Titelmissbrauch", ["Das ist erlaubt, wenn er lange Erfahrung hat", "Das ist mit Erlaubnis der Krankenkasse erlaubt", "Das ist nur innerhalb der Praxis erlaubt"],
 "Das unbefugte Führen eines akademischen Grades ist nach § 132a StGB strafbar. Es ist zudem irreführende Werbung."),
("Ein Patient stirbt während einer Behandlung in Ihrer Praxis. Wer darf die Leichenschau vornehmen?",
 "Nur eine Ärztin oder ein Arzt", ["Der anwesende Heilpraktiker", "Ein Angehöriger des Verstorbenen", "Jede Person mit Erste-Hilfe-Kurs"],
 "Die Leichenschau und die Todesbescheinigung sind nach den Bestattungsgesetzen der Länder Ärzten vorbehalten. Bis zum Eintreffen des Notarztes leisten Sie Erste Hilfe."),
]
